    with self.assertRaises(EvidenceError):validate_authorization(self.store,auth,**self.kw)
    auth['completion_ref']=self.ref('completion.json',{'hand':True})
    with self.assertRaises(EvidenceError):validate_authorization(self.store,auth,**self.kw)
